"""Fuzz the engine with random valid and invalid events; it must never crash."""
import copy, json, random, sys
sys.path.insert(0, '/workspace/submission')
sys.path.insert(0, '/workspace/tmp/tests')
from gen import gen_topology, gen_routes, gen_settings
from crosscheck.crosscheck import StreamEngine

OPS = ('patch', 'routes', 'repair', 'validate', 'bogus')

def random_patch(rng, topology, valid):
    external = sorted(topology.external_ids)
    demands = []
    counters = {}
    if valid:
        for _ in range(rng.randint(0, 6)):
            if len(external) >= 2 and rng.random() < 0.7:
                a, b = rng.sample(external, 2)
                demands.append([a, b, rng.randint(0, 10 ** 9)])
        for _ in range(rng.randint(0, 6)):
            key = rng.choice(topology.all_keys)
            flow = topology.key_flow[key]
            cap = topology.flow_cap[flow]
            if rng.random() < 0.3:
                counters[key] = None
            else:
                cell = {"perturbed": rng.randint(0, cap)}
                if rng.random() < 0.5:
                    cell['ground_truth'] = {'x': [1, None, 'y']}
                if rng.random() < 0.5:
                    cell['confidence'] = [3, 4]
                counters[key] = cell
    else:
        choice = rng.randint(0, 8)
        if choice == 0:
            return {"op": "patch", "demands": [[0, 1, 1]], "counters": {}, "extra": 1}
        if choice == 1:
            return {"op": "patch", "demands": "nope", "counters": {}}
        if choice == 2:
            return {"op": "patch", "demands": [[0, 0, 1]], "counters": {}}
        if choice == 3:
            return {"op": "patch", "demands": [[0, 1, True]], "counters": {}}
        if choice == 4:
            return {"op": "patch", "demands": [], "counters": {"nope": {"perturbed": 1}}}
        if choice == 5:
            return {"op": "patch", "demands": [], "counters": {"low_A_origination": {"wrong": 1}}}
        if choice == 6:
            return {"op": "patch", "demands": [], "counters": {"low_A_origination": 7}}
        if choice == 7:
            return {"op": "patch", "demands": [[0, 1, -5]], "counters": {}}
        return {"op": "patch", "demands": [[external[0] if external else 0, 999, 1]], "counters": {}}
    return {"op": "patch", "demands": demands, "counters": counters}


def random_events(rng, topology, count, ids):
    events = []
    plan = None
    for _ in range(count):
        op = rng.choice(OPS)
        if op == 'patch':
            events.append(random_patch(rng, topology, rng.random() < 0.6))
        elif op == 'routes':
            if rng.random() < 0.3 or not topology.external_ids:
                events.append({"op": "routes", "label": "L", "paths": None})
            else:
                candidate = gen_routes(rng, {'nodes': [{'name': topology.name_of[i], 'id': i} for i in topology.node_ids],
                                             'links': [], 'external_nodes': []})
                events.append({"op": "routes", "label": "L", "paths": None})
        elif op == 'repair':
            events.append({"op": "repair", "id": rng.choice(ids + ['newid'])})
        elif op == 'validate':
            events.append({"op": "validate", "id": rng.choice(ids + ['missing'])})
        else:
            events.append({"op": "bogus"})
    return events


def main():
    rng = random.Random(int(sys.argv[1]) if len(sys.argv) > 1 else 4242)
    rounds = int(sys.argv[2]) if len(sys.argv) > 2 else 300
    problems = 0
    for round_index in range(rounds):
        spec = gen_topology(rng, max_nodes=rng.randint(1, 10), force_external=rng.choice([None, 0, 1, 2, 3]))
        settings = gen_settings(rng, cache_slots=rng.randint(0, 4))
        events = random_events(rng, None, rng.randint(1, 25), [])
        # rebuild events with the real topology for valid patches
        from crosscheck.common_utils import Topology
        topology = Topology(spec)
        events = random_events(rng, topology, rng.randint(1, 25), ['snap0', 'snap1'])
        # seed one valid patch and one repair so validate has a target
        events.insert(0, random_patch(rng, topology, True))
        events.insert(1, {"op": "repair", "id": "snap0"})
        stream = {"topology": spec, "settings": settings, "events": events}
        try:
            engine = StreamEngine(stream)
            answers = engine.replay(events)
        except Exception as exc:
            problems += 1
            print('CRASH round', round_index, type(exc).__name__, exc)
            print(json.dumps(stream)[:1500])
            if problems > 2:
                break
            continue
        for event, answer in zip(events, answers):
            if not isinstance(answer, dict) or 'op' not in answer:
                problems += 1
                print('BAD ANSWER', round_index, event, answer)
                break
            if answer['op'] != event['op']:
                problems += 1
                print('OP MISMATCH', round_index, event['op'], answer)
                break
            if event['op'] == 'repair' and sorted(answer) != ['cache_hit', 'counters', 'id', 'links', 'op', 'order']:
                problems += 1
                print('BAD REPAIR', answer)
                break
            if event['op'] == 'validate' and sorted(answer) != ['checked', 'consistent', 'failed', 'id', 'op', 'passed']:
                problems += 1
                print('BAD VALIDATE', answer)
                break
            if event['op'] == 'patch' and sorted(answer) != ['accepted', 'op']:
                problems += 1
                print('BAD PATCH', answer)
                break
            if event['op'] == 'routes' and sorted(answer) != ['accepted', 'op']:
                problems += 1
                print('BAD ROUTES', answer)
                break
        try:
            json.dumps(answers, allow_nan=False)
        except Exception as exc:
            problems += 1
            print('NOT JSON', round_index, exc)
    print('rounds', rounds, 'problems', problems)
    return 1 if problems else 0

if __name__ == '__main__':
    sys.exit(main())
